func (p *Provider) Provide(w io.WriteSeeker) (retErr error) {
	stats.Add(numProviderProvides, 1)
	defer func() {
		if retErr != nil {
			stats.Add(numProviderProvidesFail, 1)
		}
	}()

	br := &proto.BackupRequest{
		Format:   proto.BackupRequest_BACKUP_REQUEST_FORMAT_BINARY,
		Vacuum:   p.vacuum,
		Compress: p.compress,
	}
	nRetries := 0
	for {
		if _, err := w.Seek(0, io.SeekStart); err != nil {
			return err
		}
		_, err := p.str.Backup(context.Background(), br, w)
		if err == nil {
			break
		}
		time.Sleep(p.retryInterval)
		nRetries++
		if nRetries > p.nRetries {
			return err
		}
	}
	return nil
}
```

